#include "domain/exterior_woodland.hpp"
#include "domain/connected_route.hpp"
#include <iostream>
int main(){using namespace stalthos::domain;try{stalthos::world::ConnectedRoute terrain(42);ExteriorWoodlandLayout layout;auto trees=exteriorWoodland([&](double x,double z){return terrain.triangleHeight(x,z);});if(trees.size()!=10)throw std::runtime_error("stand count");for(const auto& t:trees){if(std::abs(t.z-layout.laneZ)<7 || t.x<146 || t.id<9000)throw std::runtime_error("entry lane obstruction");if(t.y!=terrain.triangleHeight(t.x,t.z))throw std::runtime_error("rendered support");if(std::hypot(t.x-144,t.z-20)<12 || std::hypot(t.x-132,t.z-33.5)<12)throw std::runtime_error("resource obstruction");}double previous=terrain.triangleHeight(layout.entranceX,layout.laneZ);for(double x=layout.entranceX+.5;x<=layout.exitX;x+=.5){double y=terrain.triangleHeight(x,layout.laneZ);if(std::abs(y-previous)/.5>.6)throw std::runtime_error("entry grade");previous=y;}std::cout<<"EXTERIOR_WOODLAND_OK ten bounded trees clear supported lane and resource approaches\n";return 0;}catch(const std::exception&e){std::cerr<<e.what();return 1;}}
